 "content": "from collections import Counter


def transform(grid):
    """Recolor to 2 the uniform full rows/columns that are not background."""
    if not grid:
        return []
    out = [row[:] for row in grid]
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    height, width = len(grid), len(grid[0])
    marked = set()

    for r, row in enumerate(grid):
        if len(set(row)) == 1 and row[0] != background:
            marked.update((r, c) for c in range(width))
    for c in range(width):
        values = {grid[r][c] for r in range(height)}
        if len(values) == 1:
            value = next(iter(values))
            if value != background:
                marked.update((r, c) for r in range(height))

    for r, c in marked:
        out[r][c] = 2
    return out
